// may carry a plain object instead. Whatever the trigger lifted to the top level only fills gaps,
// never overwrites — the raw header is the one that says where the mail was delivered.
const headers = normaliseHeaders((t.payload && t.payload.headers) || t.headers || {});
for (const [key, value] of Object.entries({ from: t.from, to: t.to, cc: t.cc })) {
  if (headers[key] == null && typeof value === 'string' && value) headers[key] = value;
}

const sender_email = extractSender(t.from, t.From, headers.from);
// The chat trigger has neither a sender nor a destination: it stays on demo_client for local
// testing, exactly as it did before this change.
const fallback_client_id = sender_email ? null : DEMO_CLIENT_ID;
const intake = resolveIntake(headers);

// What the size guard measures. Nothing in the pipeline ever opens an attachment (Module 1 reads
// subject + text), so this is only about refusing to carry one.
const size_bytes = Number(t.sizeEstimate || t.size || 0) || 0;
let attachments = 0;
(function countParts(part) {
  if (!part) return;
  if (part.filename) attachments += 1;
  if (Array.isArray(part.parts)) part.parts.forEach(countParts);
})(t.payload);
const binaryKeys = Object.keys($input.first().binary || {});
const attachment_count = Math.max(attachments, binaryKeys.length, Array.isArray(t.attachments) ? t.attachments.length : 0);

// Thread context — lets the reply land INSIDE the sender's original RFQ thread instead of
// opening a new conversation. Gmail threads a reply on threadId + a matching subject, so the
// subject must be the original one prefixed with 'Re: ', never a synthetic one.
// Chat-trigger runs have no thread; every field is null and threading degrades to a new mail.
const thread_id = t.threadId || t.thread_id || null;
const message_id = headers['message-id'] || null;
// Only meaningful when there IS a thread to reply into — otherwise a chat run with no subject
// would ship a bare 'Re: RFQ' instead of letting the caller build a real one.
const reply_subject = thread_id ? (/^re:\s/i.test(subject) ? subject : `Re: ${subject}`) : null;
const email_context = { thread_id, message_id, reply_subject };

return [{ json: {
  sender_email,
  fallback_client_id,
  intake,
  email_meta: { headers, size_bytes, attachment_count },
  email_context,
  data: { subject, text }
} }];

